// OTHVM Sleep - agent tool proxy to the laptop MCP sleep engine.
const input = $json || {};
const payload = { action: String(input.action || 'status') };
if (input.wake_at !== undefined && input.wake_at !== '') payload.wake_at = String(input.wake_at);
if (input.time !== undefined && input.time !== '') payload.time = String(input.time);
if (input.label !== undefined && input.label !== '') payload.label = String(input.label);
if (input.session_id !== undefined && input.session_id !== '') payload.session_id = String(input.session_id);
if (input.minutes !== undefined && input.minutes !== '') payload.minutes = Number(input.minutes);
if (input.chat_id !== undefined && input.chat_id !== '') payload.chat_id = String(input.chat_id);
try {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://127.0.0.1:8765/tools/sleep',
    headers: { 'Content-Type': 'application/json', 'X-API-Key': 'REPLACE_WITH_MCP_API_KEY' },
    body: payload,
    json: true,
    timeout: 60000
  });
  return [{ json: r }];
} catch (e) {
  return [{ json: { ok: false, error: String((e && e.message) || e) } }];
}

// OTHVM — expand the generic params object into the flat fields the workflow expects.
const j = $json || {};
let p = j.params;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = {}; } }
if (!p || typeof p !== 'object' || Array.isArray(p)) p = {};
const out = Object.assign({}, p);
for (const k of ['operation', 'action', 'category']) {
  if (j[k] !== undefined && j[k] !== null && j[k] !== '') out[k] = j[k];
}
return [{ json: out }];
